<?php session_start();if(!isset($_SESSION["adminsid"])){header("Location: ../index.php?msg=Please+log+in+as+Admin");exit;}require_once __DIR__.'/../includes/db.php';$db=new db();$db->setconnection();$c=$db->getConnection();$name=trim($_POST['studentName']??'');$id=trim($_POST['studentID']??'');$email=trim($_POST['studentEmail']??'');$pass=$_POST['studentPassword']??'';$degree=trim($_POST['degree']??'');if($name===''||$id===''||$email===''||$pass===''||$degree===''){header("Location: admin_service_dashboard.php?msg=All+fields+are+required");exit;}if(!filter_var($email,FILTER_VALIDATE_EMAIL)){header("Location: admin_service_dashboard.php?msg=Invalid+email+address");exit;}$hash=password_hash($pass,PASSWORD_DEFAULT);$s=$c->prepare("INSERT INTO students(studentID,studentName,studentEmail,studentPassword,degree) VALUES(?,?,?,?,?)");$s->bind_param("sssss",$id,$name,$email,$hash,$degree);$ok=$s->execute();$s->close();$db->closeConnection();header("Location: admin_service_dashboard.php?msg=".($ok?"Student+added+successfully":"Unable+to+add+student"));exit;?>